def solve_tape_decodes(text):
    tokens = text.split()
    t = int(tokens[0])
    mod = 1_000_000_007
    out = []
    for tape in tokens[1:1 + t]:
        prev = 1
        cur = 9 if tape[0] == '?' else 0 if tape[0] == '0' else 1
        for i in range(1, len(tape)):
            a, b = tape[i - 1], tape[i]
            one = 9 if b == '?' else 0 if b == '0' else 1
            if a == '1':
                two = 10 if b == '?' else 1
            elif a == '2':
                two = 7 if b == '?' else 1 if b <= '6' else 0
            elif a == '?':
                two = 17 if b == '?' else 2 if b <= '6' else 1
            else:
                two = 0
            prev, cur = cur, (one * cur + two * prev) % mod
        out.append(str(cur))
    return '\n'.join(out)

